add_action( 'woocommerce_before_available_downloads', 'perfectpixel_downloads_sort_select' );
add_filter( 'woocommerce_customer_get_downloadable_products', 'perfectpixel_downloads_sort', 20 );

function perfectpixel_downloads_sort_options() {
	return array(
		''          => 'Νεότερα πρώτα',
		'name_asc'  => 'Όνομα Α–Ω',
		'name_desc' => 'Όνομα Ω–Α',
		'expires'   => 'Λήξη',
	);
}

function perfectpixel_downloads_current_sort() {
	$sort = isset( $_GET['dl_sort'] ) ? sanitize_key( $_GET['dl_sort'] ) : '';
	return array_key_exists( $sort, perfectpixel_downloads_sort_options() ) ? $sort : '';
}

function perfectpixel_downloads_sort_select() {
	echo '<form method="get" class="perfectpixel-downloads-sort" style="margin-bottom:1em"><label>' . esc_html( '{{downloads_sort_label}}' ) . ' <select name="dl_sort" onchange="this.form.submit()">';
	foreach ( perfectpixel_downloads_sort_options() as $key => $label ) {
		printf( '<option value="%s"%s>%s</option>', esc_attr( $key ), selected( perfectpixel_downloads_current_sort(), $key, false ), esc_html( $label ) );
	}
	echo '</select></label></form>';
}

function perfectpixel_downloads_sort( $downloads ) {
	$sort = perfectpixel_downloads_current_sort();
	if ( ! $sort || ! is_account_page() ) {
		return $downloads;
	}
	usort(
		$downloads,
		function ( $a, $b ) use ( $sort ) {
			if ( 'expires' === $sort ) {
				$ea = $a['access_expires'] ? strtotime( (string) $a['access_expires'] ) : PHP_INT_MAX;
				$eb = $b['access_expires'] ? strtotime( (string) $b['access_expires'] ) : PHP_INT_MAX;
				return $ea <=> $eb;
			}
			$cmp = strnatcasecmp( (string) $a['product_name'], (string) $b['product_name'] );
			return 'name_desc' === $sort ? -$cmp : $cmp;
		}
	);
	return $downloads;
}
